import re, os, collections

decls = []  # (name, path, recv, isMethod)
gofiles = []
for root, dirs, files in os.walk('.'):
    dirs[:] = [d for d in dirs if d not in ('node_modules','.git','web')]
    for f in files:
        if f.endswith('.go'):
            gofiles.append(os.path.join(root,f))

func_re = re.compile(r'^func\s+(?:\((\w+)\s+\*?([\w\[\]]+)\)\s+)?([A-Za-z_]\w*)\s*(?:\[[^\]]*\])?\(')
for p in gofiles:
    if not p.startswith('./internal/'): continue
    if p.endswith('_test.go'): continue
    for i, line in enumerate(open(p, encoding='utf-8', errors='ignore'), 1):
        m = func_re.match(line)
        if m:
            decls.append((m.group(3), p, m.group(2), i))

# read all files content
contents = {p: open(p, encoding='utf-8', errors='ignore').read() for p in gofiles}

counts = collections.Counter()
detail = collections.defaultdict(collections.Counter)
names = set(d[0] for d in decls)
for name in names:
    pat = re.compile(r'(?<![\w.])(?:\w+\s*\.\s*)?' + re.escape(name) + r'\s*\(')
    declpat = re.compile(r'^func\b')
    for p, c in contents.items():
        n = 0
        for line in c.split('\n'):
            if declpat.match(line): continue
            n += len(pat.findall(line))
        if n:
            counts[name] += n
            detail[name][p] = n

for name, n in counts.most_common(40):
    ds = [f"{d[1]}:{d[3]}" for d in decls if d[0]==name]
    print(n, name, "|decl:", ",".join(ds[:4]), f"({len(ds)} decls)")
EOF
