use strict; use warnings;
use File::Find;
my @gofiles;
find(sub {
  return unless -f && /\.go$/;
  my $p = $File::Find::name;
  return if $p =~ m{/(node_modules|\.git|web)/};
  push @gofiles, $p;
}, '.');

my (%decls, %declcount);
for my $p (@gofiles) {
  next unless $p =~ m{^\./internal/};
  next if $p =~ /_test\.go$/;
  open my $fh, '<', $p or next;
  my $ln = 0;
  while (my $line = <$fh>) {
    $ln++;
    if ($line =~ /^func\s+(?:\((\w+)\s+\*?([\w\[\]]+)\)\s+)?([A-Za-z_]\w*)\s*(?:\[[^\]]*\])?\(/) {
      my ($recv, $name) = ($2, $3);
      push @{$decls{$name}}, "$p:$ln" . (defined $recv ? " ($recv)" : "");
    }
  }
  close $fh;
}

my %contents;
for my $p (@gofiles) { open my $fh,'<',$p or next; local $/; $contents{$p} = <$fh>; close $fh; }

my (%counts, %bypath);
for my $name (keys %decls) {
  my $q = quotemeta($name);
  for my $p (keys %contents) {
    my $n = 0;
    for my $line (split /\n/, $contents{$p}) {
      next if $line =~ /^func\b/;
      my @m = ($line =~ /(?<![\w.])(?:\w+\s*\.\s*)?$q\s*\(/g);
      $n += scalar(@m);
    }
    if ($n) { $counts{$name} += $n; $bypath{$name}{$p} = $n; }
  }
}
for my $name (sort { $counts{$b} <=> $counts{$a} } keys %counts) {
