use strict; use warnings;
open my $lf,'<','/tmp/gofiles.txt' or die; my @gofiles = map { chomp; $_ } <$lf>; close $lf;

my (%pkgname, %contents, %filepkgdir);
for my $p (@gofiles) {
  open my $fh,'<',$p or next; local $/; my $c = <$fh>; close $fh;
  $contents{$p} = $c;
  if ($c =~ /^package\s+(\w+)/m) { $pkgname{$p} = $1; }
  (my $d = $p) =~ s{/[^/]+$}{};
  $filepkgdir{$p} = $d;
}

# declarations under internal/ (non-test)
my @decls; # {name, path, line, recv, dir, pkg}
for my $p (@gofiles) {
  next unless $p =~ m{^\./internal/}; next if $p =~ /_test\.go$/;
  open my $fh,'<',$p or next; my $ln=0;
  while (my $line = <$fh>) { $ln++;
    if ($line =~ /^func\s+(?:\(\s*\w+\s+[\*]?([\w\[\]]+)\s*\)\s+)?([A-Za-z_]\w*)\s*(?:\[[^\]]*\])?\(/) {
      push @decls, { name=>$2, recv=>$1, path=>$p, line=>$ln, dir=>$filepkgdir{$p}, pkg=>($pkgname{$p}//'') };
    }
  }
  close $fh;
}

# import alias map per file: alias -> dir
my %imports; # path -> { alias => importpath }
for my $p (@gofiles) {
  my $c = $contents{$p};
  my @lines = split /\n/, $c;
  my $in=0;
  for my $l (@lines) {
    if ($l =~ /^import\s*\(/) { $in=1; next; }
    if ($in && $l =~ /^\)/) { $in=0; next; }
    if ($in && $l =~ /^\s*(?:(\w+|\.|_)\s+)?"([^"]+)"/) {
      my ($al,$ip)=($1,$2); my $base = $ip; $base =~ s{.*/}{};
      $imports{$p}{ defined $al ? $al : $base } = $ip;
    }
    if (!$in && $l =~ /^import\s+(?:(\w+)\s+)?"([^"]+)"/) {
      my ($al,$ip)=($1,$2); my $base=$ip; $base=~s{.*/}{}; $imports{$p}{ defined $al?$al:$base } = $ip;
    }
  }
}

sub declline { my ($l)=@_; return $l =~ /^func\b/; }

my %res; # key -> {count, callers=>{path=>n}}
for my $d (@decls) {
  my $name = $d->{name}; my $q = quotemeta($name);
  my $key = ($d->{recv} ? "($d->{recv}) " : "") . $name . " @ " . $d->{path} . ":" . $d->{line};
  my $modpath = $d->{dir}; $modpath =~ s{^\./}{github.com/usememos/memos/};
  my ($tot, $tottest) = (0,0); my %callers;
  for my $p (@gofiles) {
    my $c = $contents{$p}; next unless defined $c;
    my $samepkg = ($filepkgdir{$p} eq $d->{dir}) ? 1 : 0;
    # aliases in this file pointing to declaring package
    my @al;
    if (!$samepkg && $imports{$p}) {
      for my $a (keys %{$imports{$p}}) { push @al, $a if $imports{$p}{$a} eq $modpath; }
    }
    my $n=0;
    for my $line (split /\n/, $c) {
      next if declline($line);
      if ($d->{recv}) {
        # method: count receiver-qualified calls .Name(
        my @m = ($line =~ /\.\s*$q\s*\(/g); $n += scalar(@m);
        if ($samepkg) { my @m2 = ($line =~ /(?<![\w.])$q\s*\(/g); $n += scalar(@m2); }
      } else {
        if ($samepkg) { my @m = ($line =~ /(?<![\w.])$q\s*\(/g); $n += scalar(@m); }
        for my $a (@al) { my $qa=quotemeta($a); my @m = ($line =~ /(?<![\w.])$qa\s*\.\s*$q\s*\(/g); $n += scalar(@m); }
      }
    }
    if ($n) { $callers{$p}=$n; $tot += $n; $tottest += $n if $p =~ /_test\.go$/; }
  }
  $res{$key} = { tot=>$tot, test=>$tottest, callers=>{%callers} };
}

open my $out,'>','/tmp/fanin2_detail.txt' or die;
for my $k (sort { $res{$b}{tot} <=> $res{$a}{tot} } keys %res) {
  printf "%5d (nontest %3d, test %3d)  %s\n", $res{$k}{tot}, $res{$k}{tot}-$res{$k}{test}, $res{$k}{test}, $k;
  print $out "=== $k  total=$res{$k}{tot}\n";
  my $cl = $res{$k}{callers};
  for my $p (sort { $cl->{$b} <=> $cl->{$a} || $a cmp $b } keys %$cl) { print $out "    $cl->{$p}  $p\n"; }
}
close $out;
EOF
